function removeImpossibleData(timeFrames) {
    let prevFr = null;
    for(let i=timeFrames.length-1; i >= 0 ; i--) {
        const f = timeFrames[i];
        let removeWind = false;
        if (f.tws > 100)
            removeWind = true;
        // if (prevFr != null && prevFr.tws > 8 && f.tws / prevFr.tws > 3)
        //     removeWind = true;
        // if (prevFr != null && f.tws - prevFr.tws > 15)
        //     removeWind = true;
        if (removeWind) {
            console.log("removed impossible wind value:", prevFr.t,prevFr.tws, f.t,f.tws);
            // console.log(JSON.stringify(prevFr),JSON.stringify(f));
            timeFrames.splice(i,1);
        } else {
            prevFr = f;
        }
    }
    return timeFrames;
}

function rollingAverage(timeFrames, resolutionSeconds = 1, windowSeconds=3) {
    let filteredTimeFrames = [];
    let start = 0;
    let outputTs = timeFrames[0].t.clone().add(resolutionSeconds, 'seconds').milliseconds(0);
    for(let i=0; i < timeFrames.length;i++) {
        let currentTs = timeFrames[i].t;
        if (currentTs.isSameOrAfter(outputTs)) {
            while (start < timeFrames.length && currentTs.diff(timeFrames[start].t, 'seconds') > windowSeconds) {
                start++;
            }
            const frames = timeFrames.slice(start, i + 1);
            filteredTimeFrames.push(
                createEmptyTimeFrame(
                    outputTs.clone(),
                    averageAngle(frames, f => f.twa),
                    averageValue(frames, 0, f => f.tws),
                    averageValue(frames, 2, f => f.bs),
                    averageValue(frames, null, f => f.lat),
                    averageValue(frames, null, f => f.lon),
                    averageValue(frames, 2, f => f.sog),
                    averageAngle(frames, f => f.th),
                    averageAngle(frames, f => f.awa),
                    averageValue(frames, 2, f => f.aws),
                    averageValue(frames, 2, f => f.p),
                    averageValue(frames, 2, f => f.r)
                )
            );
            outputTs.add(resolutionSeconds, 'second');       
        }
    }
    return filteredTimeFrames;
}

