const NMEA_VWR = /\$..VWR,([0-9.]+),(L|R),([0-9.]+),N/;
export function storeApparentWindFromVWR(line, frame) {
    const match = line.match(NMEA_VWR);
    if (match) {
        let awa = parseFloat(match[1]);
        const awaDir = match[2];
        if (awaDir != null && !isNaN(awa)) {
            awa = awaDir == "L" ? 360 - awa : awa;
            frame.awa.push(awa);
        }
        const aws = parseFloat(match[3]);
        if (!isNaN(aws))  
            frame.aws.push(aws);
    }
}



