function isTimeJump(newTime, oldTime) {
    // detect 10 min time jump
    //if (newTime != null && oldTime != null && (newTime.isBefore(oldTime) || newTime.diff(oldTime) > 60 * 10 * 1000)) {
    if (newTime != null && oldTime != null && (newTime.valueOf() + 1000 < oldTime.valueOf() || newTime.valueOf() - oldTime.valueOf() > 60 * 10 * 1000)) {
        console.warn("Time jump at", oldTime.toISOString(), "to", newTime.toISOString());
        return true;
    }
    return false;
}

export function validateChecksum(line) {
    if (line.startsWith("$STALK"))
        return true;
    const parts = line.split('*');
    if (parts.length == 1)
        return true;
    
    if (parts.length !== 2 || parts[1].length < 2) {
        console.warn("Couldn't match checksum content:",line);
        return false;
    }
    
    let checksum = 0;
    const content = parts[0];
    for (let i = 1; i < content.length; i++) {
        checksum ^= content.charCodeAt(i);
    }
    
    const computed = checksum.toString(16).toUpperCase().padStart(2, '0');
    const nmeaChecksum = parts[1].substring(0, 2).toUpperCase();
    
    if (computed !== nmeaChecksum) {
        console.warn(`Checksum expected ${nmeaChecksum}, got ${computed}, in [${line}]`);
        return false;
    }
    
    return true;
}

//$GPGGA,013020,4119.0358,S,17450.3759,E,2,17,0.6,-9.0,M,0.0,M,,*44
const NMEA_GGA = /^\$[A-Z][A-Z]GGA/;
function storePositionFromGPGGA(line, frame) {
    let parsedTime = null;
    if (line.match(NMEA_GGA)) {
        const fields = line.split(',');

        // Parse time
        const t = fields[1];
        if (t) {
        parsedTime = moment.utc(t, "HHmmss.SS");
        }

        // Parse latitude
        const lat = fields[2];
        const latDir = fields[3];
        if (lat && latDir) {
        const degrees = parseInt(lat.slice(0, 2), 10);
        const minutes = parseFloat(lat.slice(2));
        let latitude = degrees + minutes / 60;
        if (latDir === 'S') latitude *= -1;
        frame.lat.push(latitude);
        }

        // Parse longitude
        const lon = fields[4];
        const lonDir = fields[5];
        if (lon && lonDir) {
        const degrees = parseInt(lon.slice(0, 3), 10);
        const minutes = parseFloat(lon.slice(3));
        let longitude = degrees + minutes / 60;
        if (lonDir === 'W') longitude *= -1;
        frame.lon.push(longitude);
        }
    }
    return parsedTime;
}


//$GNRMC,012959.000,A,4119.0629,S,17450.4077,E,5.87,321.90,060425,,,D,V*11
const NMEA_RMC = /^\$[A-Z][A-Z]RMC/;
export function storePositionFromRMC(line, frame) {
    let parsedTime = null;
    if (line.match(NMEA_RMC)) {
        const fields = line.split(',');

        // Parse time
        const t = fields[1];
        const date = fields[9];
        parsedTime = moment.utc(`${date}${t}`, "DDMMYYHHmmss.SS");

        // Parse latitude
        const lat = fields[3];
        const latDir = fields[4];
        if (lat && latDir) {
        const degrees = parseInt(lat.slice(0, 2), 10);
        const minutes = parseFloat(lat.slice(2));
        let latitude = degrees + minutes / 60;
        if (latDir === 'S') latitude *= -1;
        frame.lat.push(latitude);
        }

        // Parse longitude
        const lon = fields[5];
        const lonDir = fields[6];
        if (lon && lonDir) {
        const degrees = parseInt(lon.slice(0, 3), 10);
        const minutes = parseFloat(lon.slice(3));
        let longitude = degrees + minutes / 60;
        if (lonDir === 'W') longitude *= -1;
        frame.lon.push(longitude);
        }

        // Parse speed over ground (in knots)
        const sog = fields[7];
        if (sog) {
        frame.sog.push(parseFloat(sog)); 
        }
    }

    return parsedTime;
}

