let lastAisFragment = null;

function storeAisSentence(line, aisTracks, currentTime) {
    const parts = line.split(',');
    if (parts.length < 5 || !parts[0].startsWith('!AIVDM'))
        return;

    const totalFragments = parseInt(parts[1], 10);
    const fragmentNumber = parseInt(parts[2], 10);
    const payload = parts[5];

    if (totalFragments === 2) {
        if (fragmentNumber === 1) {
            // First part: store it
            lastAisFragment = {
                parts: [payload],
                originalLine: parts.slice(0) // Clone the parts array
            };
        } else if (fragmentNumber === 2 && lastAisFragment) {
            // Second part: combine and parse
            const combinedPayload = lastAisFragment.parts[0] + payload;

            // Assemble a full NMEA line
            const mergedParts = lastAisFragment.originalLine;
            mergedParts[5] = combinedPayload;
            const fillBits = mergedParts[6].split('*')[0]; // Use fill bits from part 2
            mergedParts[6] = fillBits + mergedParts[6].slice(fillBits.length); // keep checksum
            const mergedLine = mergedParts.join(',');

            const result = parseAisSentence(mergedLine);
            lastAisFragment = null; // Clear

            if (result != null && currentTime != null) {
                result.utcTime = currentTime;
                saveAisResult(result, aisTracks);
            }
        } else {
            console.warn('Unexpected AIS fragment without first part.');
        }
    } else {
        // Normal single-part message
        const result = parseAisSentence(line);
        if (result != null && currentTime != null) {
            result.utcTime = currentTime;
            saveAisResult(result, aisTracks);
        }
    }
}



function summarizeAisTracks(aisTracks) {
    let lines = "";
    for(const mmsi in aisTracks) {
    const track = aisTracks[mmsi];
    lines += `mmsi:${mmsi}, shipName:${track.shipName}, positions:${track.positions.length}\n`;
    }
    return lines;
}

// useful info at 
// https://gpsd.gitlab.io/gpsd/AIVDM.html
function parseAisSentence(nmea) {
    function sixbitToBinary(payload) {
        let bin = '';
        for (let char of payload) {
            let val = char.charCodeAt(0) - 48;
            if (val > 40) val -= 8;
            bin += val.toString(2).padStart(6, '0');
        }
        return bin;
    }

    function getInt(bin, start, length) {
        return parseInt(bin.slice(start, start + length), 2);
    }

    function getSignedInt(bin, start, length) {
        const val = getInt(bin, start, length);
        const signBit = 1 << (length - 1);
        return (val & signBit) ? val - (1 << length) : val;
    }

    function decodeSixBitStr(bin, start, length) {
        let str = '';
        for (let i = 0; i < length; i += 6) {
            const val = parseInt(bin.slice(start + i, start + i + 6), 2);
            const char = val < 32 ? String.fromCharCode(val + 64) : String.fromCharCode(val);
            str += char;
        }
        return str.trim().replace(/@+$/, '');
    }

    if (!nmea.startsWith('!AIVDM') && !nmea.startsWith('!AIVDO')) {
        // throw new Error('Not a valid AIS NMEA sentence');
        return null;
    }

    const parts = nmea.split(',');
    const payload = parts[5];
    const fillBitsStr = parts[6].split('*')[0];
    const fillBits = parseInt(fillBitsStr, 10);
    const bin = sixbitToBinary(payload);
    const binPayload = bin.slice(0, bin.length - fillBits);

    const msgType = getInt(binPayload, 0, 6);
    const mmsi = getInt(binPayload, 8, 30);
    const result = { msgType, mmsi };

    if (msgType === 18) {
        result.speedOverGround = getInt(binPayload, 46, 10) / 10;
        result.longitude = getSignedInt(binPayload, 57, 28) / 600000;
        result.latitude = getSignedInt(binPayload, 85, 27) / 600000;
        result.courseOverGround = getInt(binPayload, 112, 12) / 10;
        result.trueHeading = getInt(binPayload, 124, 9);
        result.timestamp = getInt(binPayload, 133, 6);
    //   result.assigned = getInt(binPayload, 146, 1);
    } else if (msgType === 24) {
        result.partNumber = getInt(binPayload, 38, 2);
        if (result.partNumber === 0) {
            result.shipName = decodeSixBitStr(binPayload, 40, 120);
        } else if (result.partNumber === 1) {
        //   result.vendorId = decodeSixBitStr(binPayload, 48, 42);
            result.callsign = decodeSixBitStr(binPayload, 90, 42);
        }
    } else if(msgType === 1 || msgType === 2 || msgType === 3) {
        result.speedOverGround = getInt(binPayload, 50, 10) / 10;
        result.longitude = getSignedInt(binPayload, 61, 28) / 600000;
        result.latitude = getSignedInt(binPayload, 89, 27) / 600000;
        result.courseOverGround = getInt(binPayload, 116, 12) / 10;
        result.trueHeading = getInt(binPayload, 128, 9);
        result.timestamp = getInt(binPayload, 137, 6);
    } else if (msgType === 5) {
    result.callsign = decodeSixBitStr(binPayload, 70, 42);
    result.shipName = decodeSixBitStr(binPayload, 112, 120);
} else {
    //   result.error = `Unsupported AIS message type: ${msgType}`;
    // console.log("un parsed Message:"+JSON.stringify(result));
    return null;
    }
//   console.log("parsedAisMessage:"+JSON.stringify(result));
    return result;
}
  
  
