function dataFunctionList(lines) {
    lines = lines.slice(0,1000);
    const functions = [];
    const fVWR = testParse(storeApparentWindFromVWR, lines);
    const fMWV = testParse(storeWindFromMWV, lines);
    if (fMWV.awa.length == 0 && fVWR.awa.length > 0) {
        //TODO this branch seems to never be called and fn does not exist. validate this/fix
        functions.push(storeWindFromVWR);
        console.log('Using VWR for apparent wind as MWV does not contain it');
    }
    if (fMWV.twa.length == 0) {
        console.log('Data set does not contain TWS or TWA !!');
    }
    
    const fHDT = testParse(storeHeadingFromHDT, lines);
    const fVHW = testParse(storeSpeedFromVHW, lines);
    if (fVHW.th.length < 10 && fHDT.th.length > 0) {
        functions.push(storeHeadingFromHDT);
        console.log('Using HDT for apparent wind as VHW does not contain it');
    }

    return functions;
}

function testParse(fn, lines) {
    const frame = createEmptyRawFrame();
    for(const line of lines) {
        fn(line,frame);
    }
    return frame;
}

/**
 * Creates a new frame object for insertion into a track.
 * @param {moment|number} timestamp - Frame timestamp (moment object or unix seconds)
 * @param {number} lat - Latitude
 * @param {number} lon - Longitude
 * @returns {Object} Frame object with t, lat, lon fields
 */
export function createFrame(timestamp, lat, lon) {
    const t = typeof timestamp === 'number' 
        ? moment.unix(timestamp)
        : timestamp;
    
    return {
        t: t,
        lat: lat,
        lon: lon,
        sog: 0,
        bs: 0
    };
}
